from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        # If the array is entirely negative, dropping any element leaves only a subset of negative
        # numbers, so it can never improve the best sum.
        if max(nums) < 0:
            return max(nums)

        NEG = float('-inf')
        size = 1
        while size < n:
            size *= 2

        sum_t = [0] * (2 * size)
        pre = [NEG] * (2 * size)
        suf = [NEG] * (2 * size)
        best = [NEG] * (2 * size)

        for i in range(n):
            j = size + i
            sum_t[j] = nums[i]
            pre[j] = nums[i]
            suf[j] = nums[i]
            best[j] = nums[i]
        # padding: sum=0, pre/suf/best=NEG (already set)

        for node in range(size - 1, 0, -1):
            L, R = 2 * node, 2 * node + 1
            sum_t[node] = sum_t[L] + sum_t[R]
            pre[node] = max(pre[L], sum_t[L] + pre[R])
            suf[node] = max(suf[R], sum_t[R] + suf[L])
            best[node] = max(best[L], best[R], suf[L] + pre[R])

        def update(idx, val):
            j = size + idx
            sum_t[j] = val
            pre[j] = val
            suf[j] = val
            best[j] = val
            j //= 2
            while j:
                L, R = 2 * j, 2 * j + 1
                sum_t[j] = sum_t[L] + sum_t[R]
                pre_L = pre[L]; pre_R = pre[R]
                suf_L = suf[L]; suf_R = suf[R]
                sL = sum_t[L]; sR = sum_t[R]
                p = pre_L if pre_L >= sL + pre_R else sL + pre_R
                s = suf_R if suf_R >= sR + suf_L else sR + suf_L
                pre[j] = p
                suf[j] = s
                bL = best[L]; bR = best[R]
                cross = suf_L + pre_R
                b = bL
                if bR > b: b = bR
                if cross > b: b = cross
                best[j] = b
                j //= 2

        ans = best[1]

        positions = defaultdict(list)
        for i, x in enumerate(nums):
            positions[x].append(i)

        for v, pos_list in positions.items():
            if v >= 0:
                continue
            if len(pos_list) == n:
                continue
            for i in pos_list:
                update(i, 0)
            if best[1] > ans:
                ans = best[1]
            for i in pos_list:
                update(i, v)

        return ans
